# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İSPAT-I VÂCİB: ALLAH\'IN (C.C.) VARLIĞININ AKLÎ DELİLLERİ</text>\n  <rect x="25" y="50" width="205" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="127" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Hudûs ve İmkân Delili</text>\n  <text x="40" y="103" font-size="11" fill="#334155">• Hudûs: Âlem sonradan var</text>\n  <text x="50" y="120" font-size="10.5" fill="#475569">olmuştur (hâdistir); her hâdisin</text>\n  <text x="50" y="137" font-size="10.5" fill="#475569">bir muhdisi (yaratıcısı) vardır.</text>\n  <text x="40" y="162" font-size="11" fill="#334155">• İmkân: Varlığı ve yokluğu eşit</text>\n  <text x="50" y="179" font-size="10.5" fill="#475569">mümkün varlıkları tercih eden</text>\n  <text x="50" y="196" font-size="10.5" fill="#475569">Vâcibü\'l-Vücûd zorunludur.</text>\n  <rect x="247" y="50" width="205" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Gaye ve Nizam Delili</text>\n  <text x="262" y="103" font-size="11" fill="#334155">• Kâinattaki hassas ölçü, ahenk</text>\n  <text x="272" y="120" font-size="10.5" fill="#475569">ve yasalar tesadüfle açıklanamaz.</text>\n  <text x="262" y="148" font-size="11" fill="#334155">• Her varlığa amacına uygun</text>\n  <text x="272" y="165" font-size="10.5" fill="#475569">hikmetli bir yapı verilmiştir.</text>\n  <text x="350" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">İnayet ve İhtira Delilleri (İbn Rüşd)</text>\n  <rect x="470" y="50" width="205" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="572" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Fıtrat ve Kabûl-i Âmme</text>\n  <text x="485" y="103" font-size="11" fill="#334155">• Fıtrat: İnsanın yaratılışında</text>\n  <text x="495" y="120" font-size="10.5" fill="#475569">yüce bir Yaratıcıya inanma ve</text>\n  <text x="495" y="137" font-size="10.5" fill="#475569">sığınma eğilimi vardır (Rûm, 30).</text>\n  <text x="485" y="162" font-size="11" fill="#334155">• Kabûl-i Âmme: Tarih boyunca</text>\n  <text x="495" y="179" font-size="10.5" fill="#475569">toplumların ortak Yaratıcı inancı.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TEVHİD İLKESİ VE BURHÂN-I TEMÂNU (BİRLİK DELİLİ)</text>\n  <rect x="35" y="50" width="300" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Burhân-ı Temânu (Enbiyâ, 22)</text>\n  <text x="50" y="105" font-size="11.5" fill="#334155">&quot;Eğer yerde ve gökte Allah\'tan başka</text>\n  <text x="50" y="125" font-size="11.5" fill="#334155">ilahlar olsaydı kesinlikle ikisinin de</text>\n  <text x="50" y="145" font-size="11.5" fill="#334155">düzeni bozulurdu (fesada uğrardı).&quot;</text>\n  <text x="50" y="175" font-size="11" fill="#475569">• İki ilah olsaydı iradeleri çatışırdı;</text>\n  <text x="62" y="193" font-size="11" fill="#475569">iradesi gerçekleşmeyen aciz olur ve ilah</text>\n  <text x="62" y="211" font-size="11" fill="#475569">olamazdı. Evrendeki tek düzen tek İlahı kanıtlar.</text>\n  <rect x="365" y="50" width="300" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Tevhidin Boyutları (İhlâs Suresi)</text>\n  <text x="380" y="105" font-size="11.5" fill="#334155">• Zâtında Tevhid: Eşi, benzeri, ortağı yoktur.</text>\n  <text x="380" y="130" font-size="11.5" fill="#334155">• Sıfatlarında Tevhid: Sıfatları mutlak ve</text>\n  <text x="392" y="148" font-size="11" fill="#475569">ezelîdir; hiçbir varlığın sıfatına benzemez.</text>\n  <text x="380" y="175" font-size="11.5" fill="#334155">• Fiillerinde ve İbadette Tevhid: Yaratmada</text>\n  <text x="392" y="193" font-size="11" fill="#475569">ortağı yoktur, yalnızca O\'na kulluk edilir.</text>\n  <text x="515" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">&quot;De ki: O Allah bir tektir...&quot; (İhlâs, 1-4)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ALLAH\'IN (C.C.) ZÂTÎ (SELBÎ) VE SUBÛTÎ SIFATLARI</text>\n  <rect x="35" y="50" width="300" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Zâtî (Selbî / Tenzîhî) Sıfatlar (6)</text>\n  <text x="50" y="103" font-size="11" fill="#334155">1. Vücûd: Var olması (varlığı zorunlu)</text>\n  <text x="50" y="123" font-size="11" fill="#334155">2. Kıdem: Başlangıcının olmaması (ezelî)</text>\n  <text x="50" y="143" font-size="11" fill="#334155">3. Bekâ: Sonunun olmaması (ebedî)</text>\n  <text x="50" y="163" font-size="11" fill="#334155">4. Vahdâniyyet: Bir ve tek olması</text>\n  <text x="50" y="183" font-size="11" fill="#334155">5. Muhâlefetün li\'l-havâdis: Yaratılmışlara benzememe</text>\n  <text x="50" y="203" font-size="11" fill="#334155">6. Kıyâm bi-nefsihî: Hiçbir şeye muhtaç olmama</text>\n  <rect x="365" y="50" width="300" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Subûtî Sıfatlar (8)</text>\n  <text x="380" y="103" font-size="11" fill="#334155">1. Hayat (Diri olma) · 2. İlim (Her şeyi bilme)</text>\n  <text x="380" y="125" font-size="11" fill="#334155">3. Semî (İşitme) · 4. Basar (Görme)</text>\n  <text x="380" y="147" font-size="11" fill="#334155">5. İrade (Dileme ve seçme)</text>\n  <text x="380" y="169" font-size="11" fill="#334155">6. Kudret (Sonsuz güç sahibi olma)</text>\n  <text x="380" y="191" font-size="11" fill="#334155">7. Kelam (Konuşma / Vahiy gönderme)</text>\n  <text x="380" y="213" font-size="11" font-weight="bold" fill="#b45309">8. Tekvin (Yoktan yaratma - Mâtürîdîlik)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
